def flatten(lst):
    """Flatten a list nested to any depth. flatten([1, [2, [3, [4]]]]) -> [1, 2, 3, 4]"""
    result = []
    for i in lst:
        if isinstance(i, list):
            result.extend(flatten(i))
        else:
            result.append(i)
    return result
